"""Train a tiny byte-pair encoding (BPE) tokeniser and use it on new words.

The word counts are the classic toy example used to explain BPE. Run: python bpe.py
"""

from collections import Counter

CORPUS = {"low": 5, "lower": 2, "newest": 6, "widest": 3}


def pair_counts(vocab):
    """How often each adjacent pair of symbols occurs, weighted by word frequency."""
    counts = Counter()
    for symbols, freq in vocab.items():
        for a, b in zip(symbols, symbols[1:]):
            counts[a, b] += freq
    return counts


def merge(vocab, pair):
    """Replace every occurrence of the pair with one merged symbol."""
    out = {}
    for symbols, freq in vocab.items():
        merged, i = [], 0
        while i < len(symbols):
            if i < len(symbols) - 1 and (symbols[i], symbols[i + 1]) == pair:
                merged.append(symbols[i] + symbols[i + 1])
                i += 2
            else:
                merged.append(symbols[i])
                i += 1
        out[tuple(merged)] = freq
    return out


def train(corpus, num_merges):
    vocab = {tuple(word) + ("</w>",): freq for word, freq in corpus.items()}
    merges = []
    for _ in range(num_merges):
        counts = pair_counts(vocab)
        if not counts:
            break
        # TODO 1: pick the most frequent pair (on a tie, the one that sorts first), record it in merges,
        #         and merge it everywhere in vocab
        break
    return merges


def tokenise(word, merges):
    """Apply the learned merges, in the order they were learned."""
    symbols = tuple(word) + ("</w>",)
    for pair in merges:
        symbols = tuple(merge({symbols: 1}, pair))[0]
    return list(symbols)


def main():
    merges = train(CORPUS, 10)
    print("Merges in order:", ", ".join(a + "+" + b for a, b in merges))
    for word in ("lowest", "newer", "wider", "slowest"):
        print(f"{word:<8} -> {tokenise(word, merges)}")


if __name__ == "__main__":
    main()

